# \u26a0 \u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0645\u062a\u0637\u0644\u0628 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u2b50 (\u0644\u0648 \u062a\u0643\u0634\u064a\u0641 \u0627\u0644\u0645\u0644\u0641 \u0645\u0639\u0632\u0648\u0644 \u0628\u0633\u0628\u0628 \u062f\u0627\u062e\u0644\u064a \u2b50)
EXTERNAL = ("playwright", "chromium", "puppeteer", "localhost", "127.0.0.1",
            "octashares", "workers.dev", "railway", "preview", "live",
            "--cases", "process.argv")

RESULTS = []


def check(cond, msg, extra=""):
    RESULTS.append(bool(cond))
    print("   %s %s%s" % ("\u2705" if cond else "\u274c", msg,
                          ("  ::  " + extra) if extra else ""))
    return bool(cond)


def run_gate(gid):
    rel, reason = GATES[gid]
    print("\n\u2500\u2500 %s \u00b7 %s" % (gid, rel))
    path = os.path.join(ROOT, rel)
    if not check(os.path.isfile(path),
                 "\u0627\u0644\u0645\u0644\u0641 \u0645\u0648\u062c\u0648\u062f", rel):
        return False
    try:
        src = io.open(path, encoding="utf-8", errors="replace").read().lower()
    except Exception as e:
        return check(False, "\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0644\u0641",
                     "%s: %s" % (type(e).__name__, str(e)[:80]))
    hits = [m for m in EXTERNAL if m in src]
    ok = check(bool(hits),
               "\u0627\u0644\u0645\u0644\u0641 \u0639\u0646\u062f\u064a\u064b \u0645\u062a\u0637\u0644\u0628 \u0628\u0627\u0644\u0639\u0627\u0644\u0642 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u2b50",
               ", ".join(hits[:6]))
    check(bool(reason.strip()), "\u0627\u0644\u0633\u0628\u0628 \u0645\u0648\u062b\u0651\u0642 \u0641\u064a \u0627\u0644\u0633\u062c\u0644 \u2b50")
    return ok


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--gate", default="")
    args = ap.parse_args()
    gates = [args.gate] if args.gate else sorted(GATES)
    for gid in gates:
        if gid not in GATES:
            print("\u26d4 \u0628\u0648\u0627\u0628\u0629 \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641\u0629: %s" % gid)
            RESULTS.append(False)
            continue
        run_gate(gid)
    passed = sum(1 for r in RESULTS if r)
    print("\n==== \u0627\u0644\u0628\u0648\u0627\u0628\u0627\u062a \u0627\u0644\u0628\u062f\u064a\u0644\u0629 \u2014 %d / %d ====" % (passed, len(RESULTS)))
    return 0 if passed == len(RESULTS) else 1


if __name__ == "__main__":
    sys.exit(main())
